setup.manifest:
{
  "display_information": {
    "name": "Pylon",
    "description": "Pylon AI 에이전트가 사용자의 Slack 을 읽고 검색합니다."
  },
  "oauth_config": {
    "redirect_urls": [
      "{redirect_url}"
    ],
    "scopes": {
      "user": [
        "search:read.public",
        "search:read.private",
        "search:read.mpim",
        "search:read.im",
        "search:read.files",
        "search:read.users",
        "channels:history",
        "groups:history",
        "mpim:history",
        "im:history",
        "channels:read",
        "groups:read",
        "mpim:read",
        "im:read",
        "users:read",
        "canvases:read",
        "files:read",
        "reactions:read"
      ]
    }
  },
  "settings": {
    "org_deploy_enabled": false,
    "socket_mode_enabled": false,
    "token_rotation_enabled": false
  }
}
